/**
 * The first `</name>` at or after `from`, case-insensitive, or -1
 */
export declare function indexOfClosingTag(html: string, name: string, from: number): number;
/**
 * Remove every tag that starts with one of the prefixes, up to its `>`:
 * `removeTagsByPrefix(html, ['<meta', '<!--'])`
 */
export declare function removeTagsByPrefix(html: string, prefixes: string[]): string;
/**
 * Strip the Word wrapper tags and then the comments, as the clean-up always did
 */
export declare function removeWordWrappers(html: string): string;
/**
 * The index of the first `<name>` or `<name …>` tag, or -1
 */
export declare function indexOfOpenTag(html: string, name: string): number;
/**
 * Replace every `<name … marker …>inner</name>` with `inner`.
 * `name` null takes any tag; `keep` can refuse an element by its inner HTML.
 */
export declare function unwrapMarkedTags(html: string, name: string | null, marker: string, keep?: (inner: string) => boolean): string;
/**
 * Remove every `open … openEnd … close` block whose opener holds `marker` (any opener when it is ''):
 * `removeBetween(html, '<style', '>', '</style>', 'jodit-box')`
 */
export declare function removeBetween(html: string, open: string, openEnd: string, close: string, marker?: string): string;
/**
 * Remove every empty `<name … marker …></name>` element
 */
export declare function removeEmptyMarkedTags(html: string, name: string, marker: string): string;
